import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { createPerson, getApiError } from "./apiutils";

export default function Fill() {
    const [name, setName] = useState("");
    const [email, setEmail] = useState("");
    const [mobile, setMobile] = useState("");
    const [errorMessage, setErrorMessage] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setErrorMessage("");

        if (!name.trim() || !email.trim() || !mobile.trim()) {
            setErrorMessage("Name, email and mobile are required.");
            return;
        }

        setIsSubmitting(true);

        try {
            const response = await createPerson({ name, email, mobile });

            if (!response.success) {
                setErrorMessage(getApiError(response) || "Unable to add user.");
                return;
            }

            setName("");
            setEmail("");
            setMobile("");
            navigate("/users");
        } catch (error) {
            setErrorMessage("Something went wrong while adding the user.");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <>
            <form onSubmit={handleSubmit}>
                <div>
                    <label htmlFor="name">Name:</label>
                    <input id="name" type="text" value={name} onChange={(e) => setName(e.target.value)} />
                </div>
                <div>
                    <label htmlFor="email">Email:</label>
                    <input id="email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
                </div>
                <div>
                    <label htmlFor="mobile">Mobile:</label>
                    <input id="mobile" type="text" value={mobile} onChange={(e) => setMobile(e.target.value)} />
                </div>
                <button type="submit" disabled={isSubmitting}>
                    {isSubmitting ? "Adding..." : "Submit"}
                </button>
                {errorMessage ? <p style={{ color: "red" }}>{errorMessage}</p> : null}
            </form>
        </>
    );
}
